import java.util.LinkedHashMap;
import java.util.Map;

public class LruCacheWithTtl<K, V> extends LinkedHashMap<K, CacheEntry<V>> {
    private final int capacity;
    private final long ttlMillis;

    public LruCacheWithTtl(int capacity, long ttlMillis) {
        // true for access-order, false for insertion-order
        super(capacity, 0.75f, true);
        this.capacity = capacity;
        this.ttlMillis = ttlMillis;
    }

    @Override
    protected boolean removeEldestEntry(Map.Entry<K, CacheEntry<V>> eldest) {
        boolean sizeExceeded = size() > capacity;
        boolean expired = System.currentTimeMillis() - eldest.getValue().timestamp > ttlMillis;
        return sizeExceeded || expired;
    }

    public void putValue(K key, V value) {
        super.put(key, new CacheEntry<>(value, System.currentTimeMillis()));
    }

    public V getValue(K key) {
        CacheEntry<V> entry = super.get(key);
        if (entry == null) return null;
        if (System.currentTimeMillis() - entry.timestamp > ttlMillis) {
            super.remove(key);
            return null;
        }
        return entry.value;
    }

    private static class CacheEntry<V> {
        final V value;
        final long timestamp;
        CacheEntry(V value, long timestamp) {
            this.value = value;
            this.timestamp = timestamp;
        }
    }
}
